  3	/// The Orbs breathing ring, rendered at 64 pt in the hero slot and 20 pt inline.
  4	/// Every state keeps the same fine-line ring; only its wrapper motion changes.
  5	struct OrbView: View {
  6	    let state: OrbState
  7	    var scale: CGFloat = 1
  8	
  9	    @Environment(\.accessibilityReduceMotion) private var reduceMotion
 10	
 11	    private var orbSize: CGFloat { Theme.Orb.hero * scale }
 12	    private var slot: CGFloat { orbSize * 1.2 }
 13	    private var isInline: Bool { scale < 0.5 }
 14	
 15	    var body: some View {
 16	        TimelineView(.animation(paused: reduceMotion || isInline)) { timeline in
 17	            let time = reduceMotion || isInline ? 0 : timeline.date.timeIntervalSinceReferenceDate
 18	            let movement = motion(at: time)
 19	            ZStack {
 20	                ForEach(0..<48, id: \.self) { index in
 21	                    Capsule()
 22	                        .fill(Theme.Orb.ink)
 23	                        .frame(width: max(1, orbSize * 0.05), height: max(2, orbSize * 0.11))
 24	                        .offset(y: -orbSize * 0.39)
 25	                        .rotationEffect(.degrees(Double(index) * 7.5))
 26	                }
 27	            }
 28	            .frame(width: orbSize, height: orbSize)
 29	            .scaleEffect(movement.scale)
 30	            .rotationEffect(.degrees(movement.rotation))
 31	            .frame(width: slot, height: slot)
 32	            .animation(.timingCurve(0.4, 0, 0.2, 1, duration: Theme.Motion.base), value: state)
 33	        }
 34	        .frame(width: slot, height: slot)
 35	        .accessibilityElement()
 36	        .accessibilityLabel(Text(OrbView.title(for: state)))
 37	    }
 38	
 39	    private func motion(at time: Double) -> (scale: CGFloat, rotation: Double) {
 40	        guard !reduceMotion else { return (1, 0) }
 41	
 42	        switch state {
 43	        case .idle:
 44	            return (1 + 0.005 * sin(time * 2 * .pi / Theme.Motion.breathe), 0)
 45	        case .listening:
 46	            let phase = (time / Theme.Motion.listen).truncatingRemainder(dividingBy: 1)
 47	            let frames: [(Double, Double)] = [
 48	                (0, 0.9), (0.16, 1.16), (0.32, 0.94), (0.47, 1.08),
 49	                (0.61, 0.88), (0.78, 1.2), (0.9, 0.97), (1, 0.9),
 50	            ]
 51	            return (interpolatedScale(phase, frames: frames), 0)
 52	        case .thinking:
 53	            return (1, time / Theme.Motion.think * 360)
 54	        case .searching:
 55	            let phase = (time / Theme.Motion.act).truncatingRemainder(dividingBy: 1)
 56	            let frames: [(Double, Double)] = [
 57	                (0, 1), (0.22, 1.12), (0.34, 1), (0.56, 1.12),
 58	                (0.68, 1), (0.9, 1.12), (1, 1),
 59	            ]
 60	            return (interpolatedScale(phase, frames: frames), phase * 360)
 61	        case .speaking:
 62	            return (1 + 0.015 * sin(time * 2 * .pi / Theme.Motion.speak), 0)
 63	        }
 64	    }
 65	
 66	    private func interpolatedScale(_ progress: Double, frames: [(Double, Double)]) -> CGFloat {
 67	        for index in 1..<frames.count {
 68	            let start = frames[index - 1]
 69	            let end = frames[index]
 70	            if progress <= end.0 {
 71	                let fraction = (progress - start.0) / (end.0 - start.0)
 72	                return CGFloat(start.1 + (end.1 - start.1) * fraction)
 73	            }
 74	        }
 75	        return CGFloat(frames[frames.count - 1].1)
 76	    }
